import std.stdio;

// The `in` contract rejects arguments whose factorial would overflow a ulong.
ulong factorial(uint n) pure nothrow @safe
in (n <= 20)
{
    return n <= 1 ? 1 : n * factorial(n - 1);
}

void main()
{
    writeln(factorial(10));
}

