{
    foreach (i; 1 .. 16)
    {
        if (i % 15 == 0)
            writeln("FizzBuzz");
        else if (i % 3 == 0)
            writeln("Fizz");
        else if (i % 5 == 0)
            writeln("Buzz");
        else
            writeln(i);
    }
}

higher-order.code:
import std.algorithm : filter, map;
import std.range : iota;
import std.stdio : writefln;

void main()
{
    // A lazy range pipeline chained with UFCS: x.f!(args) means f!(args)(x).
    iota(1, 11)
        .filter!(x => x % 2 == 0)
        .map!(x => x * x)
        .writefln!"%(%s %)";
}

shapes.code:
import std.stdio;

abstract class Shape
{
    abstract string name() const;
    abstract int area() const;
}

class Rectangle : Shape
{
    int width, height;
    this(int width, int height) { this.width = width; this.height = height; }
    override string name() const { return "Rectangle"; }
    override int area() const { return width * height; }
}

class Triangle : Shape
{
    int base, height;
    this(int base, int height) { this.base = base; this.height = height; }
    override string name() const { return "Triangle"; }
    override int area() const { return base * height / 2; }
}

void main()
{
    Shape[] shapes = [new Rectangle(3, 4), new Triangle(10, 3)];
    foreach (s; shapes)
        writefln("%s: %d", s.name, s.area);
}

