import std.algorithm, std.array, std.range, std.stdio;

// Ordinary D code that builds declarations as a string...
string fields(string[] names...)
{
    return names.map!(n => "int " ~ n ~ ";").join;
}

// ...run by the compiler (CTFE) and compiled in place (mixin).
struct Vec2 { mixin(fields("x", "y")); }
struct Vec3 { mixin(fields("x", "y", "z")); }

// A template that branches on its type argument at compile time.
int total(T)(T v)
{
    static if (__traits(hasMember, T, "z")) return v.x + v.y + v.z;
    else return v.x + v.y;
}

// A lazy range pipeline run during compilation: the binary holds only the result.
enum primes = iota(2, 30).filter!(n => iota(2, n).all!(d => n % d != 0)).array;
static assert(primes.length == 10);

void main()
{
    scope (exit) writeln("done"); // runs however main is left
    writeln(total(Vec2(1, 2)), " ", total(Vec3(1, 2, 3)), " ", primes);
}
